    int i = 1;
    int interactive = 0;
    const char *prog = (argc>0? argv[0] : "executable");
    while (i < argc) {
        char *arg = argv[i];
        if (strcmp(arg, "--") == 0) {
            i++; break;
        }
        if (strcmp(arg, "-") == 0) {
            /* execute stdin: read and ignore */
            int c;
            while ((c = getchar()) != EOF) { }
            return 0;
        }
        if (arg[0] == '-' && arg[1] == '-') {
            /* unrecognized long option */
            fprintf(stderr, "%s: unrecognized option '%s'\n", prog, arg);
            fprintf(stderr, usage, prog);
            return 1;
        }
        if (arg[0] == '-' && arg[1] != '\0') {
            /* handle short options, could be combined but we will treat as whole arg */
            if (strcmp(arg, "-v") == 0) {
                printf("Lua 5.5.1  Copyright (C) 1994-2026 Lua.org, PUC-Rio\n");
                return 0;
            } else if (strcmp(arg, "-i") == 0) {
                interactive = 1;
                i++; continue;
            } else if (strcmp(arg, "-E") == 0) {
                i++; continue;
            } else if (strcmp(arg, "-W") == 0) {
                i++; continue;
            } else if (strcmp(arg, "-e") == 0) {
                /* need next argument */
                if (i+1 >= argc) {
                    fprintf(stderr, "%s: option '-e' needs an argument\n", prog);
                    return 1;
                }
                i += 2; continue;
            } else if (strcmp(arg, "-l") == 0) {
                if (i+1 >= argc) {
                    fprintf(stderr, "%s: option '-l' needs an argument\n", prog);
                    return 1;
                }
                i += 2; continue;
            } else {
                /* unknown short option */
                fprintf(stderr, "%s: unrecognized option '%s'\n", prog, arg);
                fprintf(stderr, usage, prog);
                return 1;
            }
        }
        /* not an option: treat as script name */
        /* For our implementation, we won't execute script; just exit successfully */
        return 0;
    }
    /* If reached here, no version printed, no error -> normal exit with possible interactive handling */
    if (interactive) {
        /* For simplicity, do nothing and exit 0 */
        return 0;
    }
    return 0;
}
